<script setup lang="ts">
/**
 * Tabs.Content: one tab’s panel.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tabs.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { inject } from 'vue'

import styles from '@polymorph/recipes/overlays/tabs.module.css'

export interface TabsContentProps {
  /**
   * The value of the tab this panel belongs to.
   */
  value: string
}

defineOptions({ name: 'TabsContent', inheritAttrs: false })

defineProps<TabsContentProps>()
defineSlots<{ default: (props: Record<string, never>) => unknown }>()
const owner = inject<Record<string, any>>('polymorph:Tabs', {})
</script>

<template>
  <div
    v-if="owner.keepMounted || owner.api?.value === value"
    v-bind="owner.api?.getContentProps({ value }) ?? {}"
    :class="styles.content"
    data-tabs-part="tabpanel"
    :data-state="owner.api?.value === value ? 'active' : 'inactive'"
  >
    <slot />
  </div>
</template>
